def fizzbuzz(n: int) -> list[str]:
    """Devuelve una lista de strings del 1 al n con la regla FizzBuzz."""
    result = []
    for i in range(1, n + 1):
        if i % 15 == 0:
            result.append("FizzBuzz")
        elif i % 3 == 0:
            result.append("Fizz")
        elif i % 5 == 0:
            result.append("Buzz")
        else:
            result.append(str(i))
    return result

def aplanar(lista):
    resultado = []
    for elemento in lista:
        if isinstance(elemento, list):
            resultado.extend(aplanar(elemento))
        else:
            resultado.append(elemento)
    return resultado

def buscar(lista, x):
    inicio = 0
    fin = len(lista) - 1

    while inicio <= fin:
        medio = (inicio + fin) // 2

        if lista[medio] == x:
            return medio
        elif lista[medio] < x:
            inicio = medio + 1
        else:
            fin = medio - 1

    return -1

def agrupar_por(items, clave):
    resultado = {}
    for item in items:
        valor = item[clave]
        if valor not in resultado:
            resultado[valor] = []
        resultado[valor].append(item)
    return resultado

def rotar(lista: list, n: int) -> list:
    if not lista:
        return []
    n = n % len(lista)
    return lista[-n:] + lista[:-n] if n != 0 else lista

def mayor_racha(lista: list) -> tuple | None:
    if not lista:
        return None

    max_elemento = lista[0]
    max_longitud = 1
    actual_elemento = lista[0]
    actual_longitud = 1

    for i in range(1, len(lista)):
        if lista[i] == actual_elemento:
            actual_longitud += 1
        else:
            if actual_longitud > max_longitud:
                max_longitud = actual_longitud
                max_elemento = actual_elemento
            actual_elemento = lista[i]
            actual_longitud = 1

    if actual_longitud > max_longitud:
        max_longitud = actual_longitud
        max_elemento = actual_elemento

    return (max_elemento, max_longitud)

def a_camel(s: str) -> str:
    """Convierte un texto en snake_case a camelCase."""
    palabras = s.split('_')
    return palabras[0].lower() + ''.join(palabra.capitalize() for palabra in palabras[1:])

def a_snake(s: str) -> str:
    """Convierte camelCase o PascalCase a snake_case.

    Todo en minusculas y un guion bajo antes de cada mayuscula interna.
    No debe empezar con guion bajo.
    """
    if not s:
        return s

    # Insertar guion bajo antes de cada mayúscula que no es la primera letra
    result = []
    for i, char in enumerate(s):
        if char.isupper() and i > 0 and s[i-1].islower():
            result.append('_')
        result.append(char.lower())

    return ''.join(result)

def mcd(a: int, b: int) -> int:
    """Calcula el máximo común divisor de dos enteros no negativos.

    El MCD de un número con 0 es ese número.
    """
    if a == 0 and b == 0:
        return 0
    if a == 0:
        return b
    if b == 0:
        return a

    while b != 0:
        a, b = b, a % b
    return a

def fusionar(intervalos):
    if not intervalos:
        return []

    intervalos.sort()
    fusionados = [intervalos[0]]

    for inicio, fin in intervalos[1:]:
        if inicio <= fusionados[-1][1]:
            fusionados[-1] = (fusionados[-1][0], max(fusionados[-1][1], fin))
        else:
            fusionados.append((inicio, fin))

    return fusionados

def comprimir(s: str) -> str:
    if not s:
        return s

    resultado = []
    contador = 1

    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            contador += 1
        else:
            resultado.append(s[i - 1])
            resultado.append(str(contador))
            contador = 1

    resultado.append(s[-1])
    resultado.append(str(contador))

    comprimido = ''.join(resultado)

    return comprimido if len(comprimido) < len(s) else s

def balanceado(s: str) -> bool:
    """
    Devuelve True si los paréntesis, corchetes y llaves del texto están
    correctamente balanceados y anidados. Un texto vacío está balanceado.
    """
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}
    opening = set(pairs.values())

    for char in s:
        if char in opening:
            stack.append(char)
        elif char in pairs:
            if not stack or stack[-1] != pairs[char]:
                return False
            stack.pop()

    return len(stack) == 0

