def balanceado(s: str) -> bool:
    """
    Verifica si los paréntesis, corchetes y llaves de una cadena están bien balanceados y anidados.
    Los demás caracteres se ignoran.

    Args:
        s: La cadena de texto a verificar.

    Returns:
        True si los símbolos de agrupación están balanceados, False en caso contrario.
    """
    stack = []
    pares = {')': '(', ']': '[', '}': '{'}

    for char in s:
        if char in '([{':
            stack.append(char)
        elif char in ')]}':
            if not stack or stack[-1] != pares[char]:
                return False
            stack.pop()

    return len(stack) == 0

def mediana(nums):
    if not nums:
        return None
    nums_sorted = sorted(nums)
    n = len(nums_sorted)
    mid = n // 2
    if n % 2 == 0:
        return (nums_sorted[mid - 1] + nums_sorted[mid]) / 2
    else:
        return nums_sorted[mid]

