def dedup(lista):
    seen = set()
    resultado = []
    for elemento in lista:
        if elemento not in seen:
            seen.add(elemento)
            resultado.append(elemento)
    return resultado

def anidar(plano: dict) -> dict:
    """Convierte un diccionario con claves anidadas (ej: 'a.b') en un diccionario anidado."""
    resultado = {}
    for clave, valor in plano.items():
        partes = clave.split('.')
        actual = resultado
        for parte in partes[:-1]:
            if parte not in actual:
                actual[parte] = {}
            actual = actual[parte]
        actual[partes[-1]] = valor
    return resultado

