def promedio_movil(nums, ventana):
    if len(nums) < ventana:
        return []
    return [sum(nums[i:i+ventana]) / ventana for i in range(len(nums) - ventana + 1)]

def formatear_bytes(n: int) -> str:
    """Convierte un número de bytes a una cadena legible (B, KB, MB, GB) con un decimal,
    excepto para B que no tiene decimales."""
    if n < 1024:
        return f"{n} B"
    if n < 1024 ** 2:
        return f"{n / 1024:.1f} KB"
    if n < 1024 ** 3:
        return f"{n / (1024 ** 2):.1f} MB"
    return f"{n / (1024 ** 3):.1f} GB"

