def contar_islas(grid: list[list[int]]) -> int:
    if not grid or not grid[0]:
        return 0

    filas = len(grid)
    columnas = len(grid[0])
    visitados = [[False] * columnas for _ in range(filas)]

    def dfs(fila: int, col: int) -> None:
        visitados[filo][col] = True
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            n_fila, n_col = fila + dr, col + dc
            if 0 <= n_fila < filas and 0 <= n_col < columnas:
                if not visitados[n_fila][n_col] and grid[n_fila][n_col] == 1:
                    dfs(n_fila, n_col)

    islas = 0
    for i in range(filas):
        for j in range(columnas):
            if grid[i][j] == 1 and not visitados[i][j]:
                islas += 1
                dfs(i, j)

    return islas

def distancia(a: str, b: str) -> int:
    """Calcula la distancia de edición de Levenshtein entre dos strings."""
    m, n = len(a), len(b)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = 1 + min(
                    dp[i - 1][j],      # borrado
                    dp[i][j - 1],      # inserción
                    dp[i - 1][j - 1]   # sustitución
                )
    return dp[m][n]

import re

def validar_password(p: str) -> bool:
    if len(p) < 8:
        return False
    if not re.search(r'[A-Z]', p):
        return False
    if not re.search(r'[a-z]', p):
        return False
    if not re.search(r'[0-9]', p):
        return False
    if not re.search(r'[^A-Za-z0-9]', p):
        return False
    return True

def interseccion(a: list[int], b: list[int]) -> list[int]:
    """Devuelve la lista ordenada de valores presentes en ambas listas, sin repetidos."""
    return list(set(a) & set(b))

