    if '"' in s or ',' in s or '\n' in s:
        s = s.replace('"', '""')
        return f'"{s}"'
    return s

def titular(s: str) -> str:
    """
    Pone en mayúscula la primera letra de cada palabra,
    excepto 'de', 'del', 'la', 'las', 'el', 'los' e 'y'
    cuando no son la primera palabra.
    Las demás letras quedan en minúscula.
    """
    palabras = s.split()
    mayusculas = {'de', 'del', 'la', 'las', 'el', 'los', 'y'}
    resultado = []

    for i, palabra in enumerate(palabras):
        if i == 0:
            resultado.append(palabra.capitalize())
        elif palabra.lower() in mayusculas:
            resultado.append(palabra.lower())
        else:
            resultado.append(palabra.capitalize())

    return ' '.join(resultado)

def sumar_romanos(a: str, b: str) -> str:
    """Suma dos números romanos y devuelve el resultado en romano."""
    simbolos = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50,
        'C': 100, 'D': 500, 'M': 1000
    }

    def romano_a_entero(s: str) -> int:
        total = 0
        valor_anterior = 0
        for char in reversed(s):
            valor = simbolos[char]
            if valor < valor_anterior:
                total -= valor
            else:
                total += valor
            valor_anterior = valor
        return total

    def entero_a_romano(n: int) -> str:
        valores = [1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1]
        simbolos = ['M', 'CM', 'D', 'CD', 'C', 'XC', 'L', 'XL', 'X', 'IX', 'V', 'IV', 'I']
        resultado = ""
        for valor, simbolo in zip(valores, simbolos):
            while n >= valor:
                resultado += simbolo
                n -= valor
        return resultado

    suma = romano_a_entero(a) + romano_a_entero(b)
    return entero_a_romano(suma)

def con_reintentos(fn, veces):
    for _ in range(veces):
        try:
            return fn()
        except Exception:
            pass
    raise
